typedef struct {
    int data[4];
    int head, count;
} Queue;

void enqueue(Queue *q, int x) {
    int b = (q->head + q->count) % 4;
    q->data[b] = x;
    q->count++;
}

int dequeue(Queue *q) {
    int x = q->data[q->head];
    q->head = (q->head + 1) % 4;
    q->count--;
    return x;
}
